	/**
	 * Returns a menu href, relocating the two built-in NONE landing links under the current Workbench mount.
	 *
	 * @param request current request
	 * @param itemId  menu item ID
	 * @param href    validated policy href
	 * @return mount-aware href for the built-in landing links, otherwise the original href
	 */
